/**
 * Johndorf's project pages (/projects/<slug>) — everything on each project's page at
 * sitedev.johndorfventures.com/project/<slug>/ (the site behind johndorfventures.com),
 * read 2026-10-05: hero photos, map, site development plan, unit types with their
 * renders and specs, amenities, and the construction updates month by month.
 * Images were copied to S3 (jvconline/johndorf/projects/<slug>/…) at web sizes.
 * Generated by johndorf-handoff/project-data/site-parse.py + gen — do not edit figures by hand.
 */

export type JdSpecs = { usable_floor_area: string | null; typical_floor_area: string | null; bedrooms: string | null; baths: string | null; floors: string | null; parking: string | null }
export type JdUnitType = { name: string; images: string[]; specs: JdSpecs | null }
export type JdUpdateMonth = { key: string; label: string; photos: string[] }
export type JdSiteProject = {
  slug: string
  officialUrl: string
  hero: string[]
  map: { lat: number; lng: number } | null
  mapQuery: string | null
  sitePlans: string[]
  unitTypes: JdUnitType[]
  amenities: string[]
  updates: JdUpdateMonth[]
}

export const SPEC_LABELS: Record<keyof JdSpecs, string> = {
  "usable_floor_area": "Usable floor area",
  "typical_floor_area": "Typical floor area",
  "bedrooms": "Bedrooms",
  "baths": "Toilet & bath",
  "floors": "Floors",
  "parking": "Parking"
}

